import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"使用指南","description":"按部署、首次分析、日常使用、AI 接入和自动更新五条路线找到下一步。","frontmatter":{"page_id":"guide-index","title":"使用指南","description":"按部署、首次分析、日常使用、AI 接入和自动更新五条路线找到下一步。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786627803000}'),o={name:"guide/index.md"};function l(n,a,d,h,s,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><p>第一次接触 Ershu，不需要把所有配置页从头读完。先选与你当前目标一致的路线。</p><h2 id="我想先把它跑起来" tabindex="-1">我想先把它跑起来 <a class="header-anchor" href="#我想先把它跑起来" aria-label="Permalink to &quot;我想先把它跑起来&quot;">​</a></h2><ol><li><a href="./quick-start">在 Linux 服务器上快速部署 Ershu</a></li><li><a href="./create-first-project">创建第一个项目</a></li><li><a href="./follow-a-run">开始并跟踪第一次分析</a></li></ol><p>这条路线下载部署包，从 PyPI 安装后端，用 systemd 启动服务，再部署已经构建好的前端。服务器不需要源码仓或 Node.js。</p><h2 id="我准备长期部署" tabindex="-1">我准备长期部署 <a class="header-anchor" href="#我准备长期部署" aria-label="Permalink to &quot;我准备长期部署&quot;">​</a></h2><p>先完成单机验证，再看<a href="./production-deployment">把快速部署改成生产部署</a>。生产页说明 HTTPS、正式配置、备份、Worker 权限和升级顺序。</p><h2 id="我已经有分析结果-想真正用起来" tabindex="-1">我已经有分析结果，想真正用起来 <a class="header-anchor" href="#我已经有分析结果-想真正用起来" aria-label="Permalink to &quot;我已经有分析结果，想真正用起来&quot;">​</a></h2><ul><li><a href="./read-search-chat">阅读 Wiki、搜索项目和继续提问</a></li><li><a href="./debugging">定位分析、检索和关系问题</a></li></ul><p>Docs 适合按主题理解项目，Search 适合定位具体实现，项目问答适合综合多个来源。无论从哪里进入，精确结论都应能回到当前源码核对。</p><h2 id="我想让-ai-编程工具读取项目" tabindex="-1">我想让 AI 编程工具读取项目 <a class="header-anchor" href="#我想让-ai-编程工具读取项目" aria-label="Permalink to &quot;我想让 AI 编程工具读取项目&quot;">​</a></h2><p>看<a href="./connect-mcp">接入 MCP 客户端</a>。先创建项目范围密钥，再用 <code>get_server_info</code>、项目发现、Wiki、搜索和源码读取逐步验证连接。MCP 是只读入口，不会替客户端修改仓库。</p><h2 id="我想让资料跟着仓库更新" tabindex="-1">我想让资料跟着仓库更新 <a class="header-anchor" href="#我想让资料跟着仓库更新" aria-label="Permalink to &quot;我想让资料跟着仓库更新&quot;">​</a></h2><p>看<a href="./automation">自动跟进仓库更新</a>。计划轮询和签名 Webhook 都只负责发现提交并创建刷新任务，实际处理仍依赖 Worker。</p><h2 id="三个容易混淆的边界" tabindex="-1">三个容易混淆的边界 <a class="header-anchor" href="#三个容易混淆的边界" aria-label="Permalink to &quot;三个容易混淆的边界&quot;">​</a></h2><ul><li><strong>进程存活不等于整套系统可用。</strong> API 健康页不检查 Worker、Redis 或模型通道。</li><li><strong>任务入队不等于任务完成。</strong> Worker 没运行时，任务会停在 <code>queued</code>。</li><li><strong>事实刷新不等于重写 Wiki。</strong> 自动刷新更新目录、代码索引、搜索索引和知识关系；需要新文档时要发起包含文档生成的分析。</li></ul>',16)])])}const f=e(o,[["render",l]]);export{p as __pageData,f as default};
